//源表：setting_tips.xlsx（设置中玩法说明表）
#pragma warning disable 8981

using System.Collections.Generic;
using System.IO;

namespace Ros.Config
{
    public partial class ConfigManager
    {
        public Dictionary<int, setting_tips> setting_tipsData;
        public setting_tips Getsetting_tipsConfig(int key)
        {
            return ConfigBinary.Require(setting_tipsData, key, "setting_tips");
        }
        private void Loadsetting_tipsConfig()
        {
            using (BinaryReader r = ConfigBinary.Open("setting_tips"))
            {
                int count = r.ReadInt32();
                setting_tipsData = new Dictionary<int, setting_tips>(count);
                for (int i = 0; i < count; i++)
                {
                    setting_tips row;
                    row.key = r.ReadInt32();
                    row.name = ConfigBinary.ReadString(r);
                    row.text = ConfigBinary.ReadString(r);
                    setting_tipsData.Add(row.key, row);
                }
            }
        }
    }
    public struct setting_tips
    {
        public int key;  // 主键
        public string name;  // 栏目名称
        public string text;  // 内容：富文本，{\n} 表示换行
    }
}
